import json,pathlib
HTML='''<!doctype html><meta charset="utf-8"><title>Robocon 教学仿真</title><style>
body{font:16px system-ui,"Microsoft YaHei",sans-serif;color:#18334d;background:#f5f7fa;margin:24px;max-width:1250px}h1{font-size:25px}button,select{font:inherit;padding:7px 14px;margin-right:8px}input{width:500px}svg{background:white;border:1px solid #bdcbd6;width:100%;max-width:1100px}p{line-height:1.7}#status{white-space:pre-wrap;font-family:monospace}table{border-collapse:collapse;background:white}td,th{border:1px solid #ccd5dc;padding:8px 16px}th{background:#e8eef4}
</style><h1>路径规划与 RoboMaster PID 控制教学仿真</h1><p>教学平面示例，不是正式比赛场地图。定位反馈来自仿真模型，不是 FAST-LIO 实测结果。蓝线为规划路径，橙线为实际运动轨迹，浅灰区为规划安全余量。</p>
<p><button id="play">播放</button><button id="reset">回到开始</button><select id="speed"><option value="1">1 倍速</option><option value="2">2 倍速</option><option value="4">4 倍速</option></select><input id="slider" type="range" min="0" value="0"><span id="clock"></span></p>
<svg id="map" viewBox="0 0 1200 800" aria-label="规划路线与仿真底盘"></svg><p id="status"></p><div id="metrics"></div>
<script>const D=__DATA__;const svg=document.getElementById('map'),S='http://www.w3.org/2000/svg';
function e(tag,attrs,text){const a=document.createElementNS(S,tag);Object.entries(attrs).forEach(([k,v])=>a.setAttribute(k,v));if(text)a.textContent=text;svg.appendChild(a);return a}
const X=x=>x*100,Y=y=>800-y*100;
for(let x=0;x<=12;x++)e('line',{x1:X(x),y1:0,x2:X(x),y2:800,stroke:'#e5ebf0'});for(let y=0;y<=8;y++)e('line',{x1:0,y1:Y(y),x2:1200,y2:Y(y),stroke:'#e5ebf0'});
const R=D.radius_m;D.obstacles.forEach(([a,b,c,d])=>{e('rect',{x:X(a-R),y:Y(d+R),width:(c-a+2*R)*100,height:(d-b+2*R)*100,rx:R*100,fill:'#e2e8ef'});e('rect',{x:X(a),y:Y(d),width:(c-a)*100,height:(d-b)*100,fill:'#718294'})});
D.plans.forEach(p=>{if(p.path.length)e('polyline',{points:p.path.map(([x,y])=>[X(x),Y(y)].join(',')).join(' '),fill:'none',stroke:'#2877bc','stroke-width':4});let [x,y]=p.goal;e('circle',{cx:X(x),cy:Y(y),r:7,fill:'#218556'});e('text',{x:X(x)+12,y:Y(y)-12,'font-size':19,fill:'#18334d'},p.name)});
let trail=e('polyline',{fill:'none',stroke:'#e88727','stroke-width':3}),robot=e('polygon',{fill:'#e88727',stroke:'#7d450d','stroke-width':2}),heading=e('line',{stroke:'#542f0f','stroke-width':4});
let i=0,playing=false,last=0;const slider=document.getElementById('slider');slider.max=Math.max(0,D.frames.length-1);
function draw(k){i=Math.min(D.frames.length-1,Math.max(0,Math.round(k)));slider.value=i;let p=D.frames[i];if(!p){robot.setAttribute('points','');document.getElementById('status').textContent=D.status+'：没有可行路线，未下发运动。';return}
trail.setAttribute('points',D.frames.slice(0,i+1).map(p=>`${X(p.x)},${Y(p.y)}`).join(' '));let [l,w]=D.field.robot_size_m;const pts=[[-l/2,-w/2],[l/2,-w/2],[l/2,w/2],[-l/2,w/2]].map(([x,y])=>[X(p.x+x*Math.cos(p.yaw)-y*Math.sin(p.yaw)),Y(p.y+x*Math.sin(p.yaw)+y*Math.cos(p.yaw))]);robot.setAttribute('points',pts.map(a=>a.join(',')).join(' '));heading.setAttribute('x1',X(p.x));heading.setAttribute('y1',Y(p.y));heading.setAttribute('x2',X(p.x+.5*Math.cos(p.yaw)));heading.setAttribute('y2',Y(p.y+.5*Math.sin(p.yaw)));document.getElementById('clock').textContent=p.t.toFixed(2)+' s';document.getElementById('status').textContent=`${p.stage}  ${p.state}\nx=${p.x.toFixed(3)} m  y=${p.y.toFixed(3)} m  yaw=${(p.yaw*180/Math.PI).toFixed(1)}°\nvx=${p.vx.toFixed(3)} m/s  vy=${p.vy.toFixed(3)} m/s  ω=${p.w.toFixed(3)} rad/s  定位年龄=${p.pose_age.toFixed(3)} s`}
document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'暂停':'播放';last=0};document.getElementById('reset').onclick=()=>{playing=false;draw(0)};slider.oninput=()=>{playing=false;draw(+slider.value)};
function tick(t){if(playing&&D.frames.length){if(!last)last=t;const step=(t-last)/50*+document.getElementById('speed').value;if(step>=1){draw(i+step);last=t;if(i>=D.frames.length-1)playing=false}}requestAnimationFrame(tick)}requestAnimationFrame(tick);draw(0);
document.getElementById('metrics').innerHTML='<p>结果：'+D.status+'　规划长度：'+D.path_length_m.toFixed(2)+' m　仿真耗时：'+D.elapsed_s.toFixed(2)+' s　碰撞记录：'+D.collision_count+'</p><table><tr><th>任务点</th><th>位置误差 m</th><th>角度误差 °</th><th>本段耗时 s</th></tr>'+D.goals.map(g=>`<tr><td>${g.name}</td><td>${g.position_error_m.toFixed(4)}</td><td>${g.yaw_error_deg.toFixed(2)}</td><td>${g.time_s.toFixed(2)}</td></tr>`).join('')+'</table>';
</script>'''
def write_viewer(data,path):
 pathlib.Path(path).write_text(HTML.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')),encoding='utf-8')
